export const getGoogleFormsWebhookUrl = () => {




  return `/api/webhook/google-forms`
}

/**
 * @summary Receive Google Forms submissions
 */
export const googleFormsWebhook = async (webhookPayload: WebhookPayload, options?: RequestInit): Promise<WebhookResult> => {

  return customFetch<WebhookResult>(getGoogleFormsWebhookUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      webhookPayload,)
  }
);}




export const getGoogleFormsWebhookMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof googleFormsWebhook>>, TError,{data: BodyType<WebhookPayload>}, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof googleFormsWebhook>>, TError,{data: BodyType<WebhookPayload>}, TContext> => {

const mutationKey = ['googleFormsWebhook'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof googleFormsWebhook>>, {data: BodyType<WebhookPayload>}> = (props) => {
          const {data} = props ?? {};

          return  googleFormsWebhook(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type GoogleFormsWebhookMutationResult = NonNullable<Awaited<ReturnType<typeof googleFormsWebhook>>>
    export type GoogleFormsWebhookMutationBody = BodyType<WebhookPayload>
    export type GoogleFormsWebhookMutationError = ErrorType<unknown>

    /**
 * @summary Receive Google Forms submissions
 */
export const useGoogleFormsWebhook = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof googleFormsWebhook>>, TError,{data: BodyType<WebhookPayload>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof googleFormsWebhook>>,
        TError,
        {data: BodyType<WebhookPayload>},
        TContext
      > => {
      return useMutation(getGoogleFormsWebhookMutationOptions(options));
    }

